let operationRequestCounter=0;
function newRequestId(){operationRequestCounter+=1;try{return crypto.randomUUID();}catch(e){return `${Date.now()}-${userId}-${operationRequestCounter}-${Math.random().toString(16).slice(2)}`;}}
function setConnectionState(online){const b=byId('connectionBanner');if(!b)return;b.classList.toggle('hidden',online);byId('syncPill').textContent=online?'Связь есть':'Нет связи';}
window.addEventListener('online',()=>{setConnectionState(true);syncOperationQueue(true);});window.addEventListener('offline',()=>setConnectionState(false));setConnectionState(navigator.onLine);
async function apiFetch(url,options={},timeoutMs=25000){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeoutMs);try{const response=await fetch(url,{...options,signal:controller.signal});setConnectionState(true);return response;}catch(error){setConnectionState(false);if(error?.name==='AbortError')throw new Error('Сервер не ответил вовремя. Попробуйте ещё раз.');throw new Error('Нет связи с сервером. Данные остались в черновике.');}finally{clearTimeout(timer);}}
function setOperationBusy(busy){state.operation_busy=busy;document.querySelectorAll('[data-action="save-work-entry"],#confirmOperationButton').forEach(btn=>{btn.classList.toggle('is-loading',busy);btn.disabled=busy;});}
function draftKey(){return `prodMiniDraft:${chatId}:${userId}`;}
function saveWorkDraft(){if(!chatId||!userId)return;const draft={operation:val('workOperation'),entity:val('workEntity'),entityCode:val('workEntityCode'),area:val('workArea'),from:val('workFromArea'),to:val('workToArea'),quantity:val('workQuantity'),note:val('workNote'),clientRequestId:state.active_queue_request_id||'',taskId:state.active_task_id||null,lotId:val('workLot')||null,savedAt:Date.now()};localStorage.setItem(draftKey(),JSON.stringify(draft));const status=byId('draftStatus');if(status)status.textContent='Черновик сохранён.';}
function restoreWorkDraft(){let draft=null;try{draft=JSON.parse(localStorage.getItem(draftKey())||'null');}catch(e){}if(!draft)return;if(draft.operation&&[...byId('workOperation').options].some(x=>x.value===String(draft.operation)))byId('workOperation').value=String(draft.operation);updateWorkEntry();if(draft.entity&&[...byId('workEntity').options].some(x=>x.value===String(draft.entity)))byId('workEntity').value=String(draft.entity);if(draft.area)byId('workArea').value=String(draft.area);if(draft.from)byId('workFromArea').value=String(draft.from);if(draft.to)byId('workToArea').value=String(draft.to);byId('workQuantity').value=draft.quantity||'';byId('workNote').value=draft.note||'';if(byId('workEntityCode'))byId('workEntityCode').value=draft.entityCode||'';state.active_queue_request_id=draft.clientRequestId||null;state.active_task_id=draft.taskId||null;if(draft.lotId&&byId('workLot'))byId('workLot').value=String(draft.lotId);renderWorkTaskContext();updateWorkStockHint();}
function clearWorkDraft(preserveContext=false){const taskId=state.active_task_id,lotId=val('workLot')||state.active_lot_id;localStorage.removeItem(draftKey());['workQuantity','workNote','workEntitySearch','workEntityCode'].forEach(id=>{if(byId(id))byId(id).value='';});state.active_preset_id=null;state.active_queue_request_id=null;if(!preserveContext){state.active_task_id=null;state.active_lot_id=null;}else{state.active_task_id=taskId||null;state.active_lot_id=lotId?Number(lotId):null;}renderWorkTaskContext();updateWorkLotChoices();const status=byId('draftStatus');if(status)status.textContent='Черновик сохраняется автоматически.';updateWorkStockHint();if(preserveContext)saveWorkDraft();}
function operationQueueKey(){return `prodMiniQueue:${chatId}:${userId}`;}
function shiftPackageIdentityKey(){return `prodMiniShiftPackage:${chatId}:${userId}`;}
function currentShiftPackageId(){let saved=null;try{saved=JSON.parse(localStorage.getItem(shiftPackageIdentityKey())||'null');}catch(e){}const shiftId=Number(state.current_open_shift?.id||0);const hasQueue=(state.operation_queue||[]).length>0;if(!saved||!saved.id||(!hasQueue&&Number(saved.shiftId||0)!==shiftId)){saved={id:newRequestId(),shiftId,createdAt:Date.now()};localStorage.setItem(shiftPackageIdentityKey(),JSON.stringify(saved));}return saved.id;}
function rotateShiftPackageId(){localStorage.removeItem(shiftPackageIdentityKey());}
function loadOperationQueue(){let items=[];try{items=JSON.parse(localStorage.getItem(operationQueueKey())||'[]');}catch(e){}state.operation_queue=Array.isArray(items)?items.slice(0,200):[];renderOperationQueue();if(navigator.onLine&&state.operation_queue.length)setTimeout(()=>syncOperationQueue(true),350);}
function persistOperationQueue(){localStorage.setItem(operationQueueKey(),JSON.stringify((state.operation_queue||[]).slice(0,200)));renderOperationQueue();}
function queuedEntity(item){return (state.work_access||[]).flatMap(x=>x.entities||[]).find(x=>Number(x.id)===Number(item?.body?.entity_id))||null;}
function queueStatusLabel(status){return ({pending:'ожидает отправки',warning:'нужно подтверждение',error:'ошибка отправки',sending:'отправляется'})[status]||status;}
function renderOperationQueue(){const box=byId('operationQueueList'),count=byId('operationQueueCount'),items=state.operation_queue||[];if(count)count.textContent=String(items.length);if(!box)return;box.innerHTML='';box.classList.toggle('empty',!items.length);if(!items.length){box.textContent='Очередь пуста';return;}items.forEach((item,index)=>{const entity=queuedEntity(item),body=item.body||{},row=document.createElement('div');row.className=`quick-action-card queue-card ${item.status||'pending'}`;const place=body.from_area_id&&body.to_area_id?`${(state.areas||[]).find(x=>Number(x.id)===Number(body.from_area_id))?.name||'Откуда'} → ${(state.areas||[]).find(x=>Number(x.id)===Number(body.to_area_id))?.name||'Куда'}`:((state.areas||[]).find(x=>Number(x.id)===Number(body.area_id))?.name||'Общий склад');const error=item.last_error?` · ${item.last_error}`:'';const buttons=item.status==='warning'?`<button data-review-queue-item="${index}">Проверить</button>`:`<button data-retry-queue-item="${index}">Отправить</button>`;row.innerHTML=`<div><b>${escapeHtml(entity?.name||item.entity_name||'Позиция')} · ${escapeHtml(fmt(body.quantity))} ${escapeHtml(body.unit||entity?.unit||'шт')}</b><span>${escapeHtml(operationLabels[body.operation_type]||body.operation_type)} · ${escapeHtml(place)}</span><span class="queue-status ${escapeHtml(item.status||'pending')}">${escapeHtml(queueStatusLabel(item.status||'pending')+error)}</span></div><div class="mini-actions">${buttons}<button data-edit-queue-item="${index}">Изменить</button><button class="danger" data-delete-queue-item="${index}">Убрать</button></div>`;box.appendChild(row);});}
function enqueueOperation(body,message='Добавлено в список смены.',confirmedWarnings=false){if(!body){showNotice('Выберите действие, позицию и количество.',true);return false;}if((state.operation_queue||[]).length>=200){showNotice('Очередь заполнена. Сначала отправьте накопленные записи.',true);return false;}const prepared={...body,client_request_id:body.client_request_id||newRequestId(),confirm_warnings:!!confirmedWarnings,preview_fingerprint:body.preview_fingerprint||''};state.operation_queue.push({body:prepared,status:'pending',created_at:new Date().toISOString(),attempts:0,last_error:'',preview:null});persistOperationQueue();clearWorkDraft();showNotice(message);return true;}
function queueCurrentOperation(){const body=currentWorkBody();if(!body){showNotice('Выберите действие, позицию и количество.',true);return;}enqueueOperation(body);}
function removeQueueItem(index){state.operation_queue.splice(Number(index),1);persistOperationQueue();}
function editQueueItem(index){const item=state.operation_queue[Number(index)];if(!item)return;const body=item.body||{};removeQueueItem(index);applyOperationTemplate(body,body.preset_id||null);state.active_queue_request_id=body.client_request_id||newRequestId();saveWorkDraft();showNotice('Запись возвращена в форму.');}
async function processQueueItem(item,forceWarnings=false){item.status='sending';item.attempts=Number(item.attempts||0)+1;item.last_error='';persistOperationQueue();try{const previewRes=await apiFetch('/api/operations/preview',{method:'POST',headers,body:JSON.stringify({...item.body,confirm_warnings:false})});const previewData=await previewRes.json().catch(()=>({}));if(!previewRes.ok){item.status='error';item.last_error=typeof previewData.detail==='string'?previewData.detail:'Проверка не пройдена';return false;}item.preview=previewData.preview||{};item.body.preview_fingerprint=item.preview.fingerprint||'';if(item.preview.requires_confirmation&&!forceWarnings&&!item.body.confirm_warnings){item.status='warning';item.last_error=(item.preview.warnings||[])[0]||'Нужно подтверждение';return false;}const saveRes=await apiFetch('/api/operations',{method:'POST',headers,body:JSON.stringify({...item.body,confirm_warnings:forceWarnings||!!item.body.confirm_warnings})});const saveData=await saveRes.json().catch(()=>({}));if(!saveRes.ok){const detail=saveData.detail||{};item.preview=detail.preview||item.preview;if(detail.preview){item.body.preview_fingerprint=detail.preview.fingerprint||'';item.status='warning';item.last_error=detail.message||'Данные изменились, подтвердите заново';}else{item.status='error';item.last_error=typeof detail==='string'?detail:(detail.message||'Не удалось сохранить');}return false;}state.dashboard=saveData.dashboard||state.dashboard;state.recent_operations=saveData.recent_operations||state.recent_operations;state.operation_presets=saveData.operation_presets||state.operation_presets;state.inventory_positions=saveData.inventory_positions||state.inventory_positions;renderDashboard(state.dashboard||{});renderOperationShortcuts();updateWorkStockHint();return true;}catch(error){item.status='pending';item.last_error=error.message||'Нет связи';return false;}}
async function syncOperationQueue(silent=false){
  if(state.queue_syncing||!(state.operation_queue||[]).length||!navigator.onLine)return;
  state.queue_syncing=true;
  const before=state.operation_queue.length;
  try{
    const body={
      chat_id:Number(chatId),user_id:Number(userId),client_package_id:currentShiftPackageId(),
      shift_id:state.current_open_shift?.id?Number(state.current_open_shift.id):null,
      area_id:state.current_open_shift?.area_id?Number(state.current_open_shift.area_id):null,
      note:'Синхронизация списка смены',items:(state.operation_queue||[]).map(item=>({body:item.body||{},created_at:item.created_at||''}))
    };
    const res=await apiFetch('/api/shift-packages/sync',{method:'POST',headers,body:JSON.stringify(body)},60000);
    const data=await res.json().catch(()=>({}));
    if(!res.ok){showNotice(typeof data.detail==='string'?data.detail:'Пакет смены не отправлен.',true);return;}
    const results=new Map((data.package?.items||[]).map(item=>[String(item.client_request_id),item]));
    const remaining=[];
    for(const local of state.operation_queue||[]){
      const result=results.get(String(local.body?.client_request_id||''));
      if(!result){local.status='error';local.last_error='Сервер не вернул результат записи';remaining.push(local);continue;}
      if(['accepted','duplicate'].includes(result.status))continue;
      local.server_item_id=result.id;
      local.preview={...(local.preview||{}),warnings:result.warnings||[]};
      local.status=result.status==='review'?'warning':'error';
      local.last_error=result.message||((result.warnings||[])[0])||'Требуется проверка';
      remaining.push(local);
    }
    state.operation_queue=remaining;
    state.shift_packages=data.shift_packages||state.shift_packages;
    state.dashboard=data.dashboard||state.dashboard;
    state.inventory_positions=data.inventory_positions||state.inventory_positions;
    state.recent_operations=data.recent_operations||state.recent_operations;
    persistOperationQueue();renderShiftPackages();renderDashboard(state.dashboard||{});renderOperationShortcuts();updateWorkStockHint();
    const saved=before-remaining.length;
    if(!remaining.length&&data.package?.status==='accepted')rotateShiftPackageId();
    if(!silent){
      if(saved)showNotice(`На сервер передано записей: ${saved}.${remaining.length?` Требуют проверки: ${remaining.length}.`:''}`);
      else showNotice('Пакет сохранён на сервере, но записи требуют проверки.',true);
    }
  }catch(error){if(!silent)showNotice(error.message||'Пакет смены не отправлен.',true);}
  finally{state.queue_syncing=false;persistOperationQueue();}
}
function reviewQueueItem(index){const item=state.operation_queue[Number(index)];if(!item)return;const preview=item.preview||{};state.pending_queue_index=Number(index);state.pending_operation={body:{...(item.body||{})},preview};fillPreviewDialog(preview);const dialog=byId('operationConfirmDialog');if(dialog?.showModal)dialog.showModal();else showNotice('Откройте запись и подтвердите предупреждения.',true);}
function retryQueueItem(index){const item=state.operation_queue[Number(index)];if(!item)return;item.status='pending';item.last_error='';persistOperationQueue();syncOperationQueue(false);}
function clearOperationQueue(){if(!(state.operation_queue||[]).length)return;if(!confirm('Удалить все неотправленные записи с этого устройства?'))return;state.operation_queue=[];persistOperationQueue();showNotice('Очередь очищена.');}
function allWorkEntities(){const map=new Map();(state.work_access||[]).forEach(access=>(access.entities||[]).forEach(item=>map.set(Number(item.id),item)));return [...map.values()];}
async function findWorkEntityByCode(rawCode=null){const code=String(rawCode??val('workEntityCode')).trim();if(!code){showNotice('Введите или отсканируйте код.',true);return false;}let found=allWorkEntities().find(x=>String(x.code||'').trim().toUpperCase()===code.toUpperCase());if(!found){try{const q=new URLSearchParams({chat_id:chatId,user_id:userId,code});const res=await apiFetch('/api/entity-codes/resolve?'+q.toString(),{headers});const data=await res.json().catch(()=>({}));if(!res.ok){showNotice(typeof data.detail==='string'?data.detail:'Код не найден.',true);return false;}found=data.entity;}catch(error){showNotice(error.message,true);return false;}}const access=(state.work_access||[]).find(x=>(x.entities||[]).some(e=>Number(e.id)===Number(found.id)));if(!access){showNotice('Эта позиция недоступна для ваших действий.',true);return false;}byId('workOperation').value=access.operation_key;updateWorkEntry();byId('workEntity').value=String(found.id);byId('workEntityCode').value=String(found.code||code);updateWorkStockHint();saveWorkDraft();showNotice(`Выбрано: ${found.name}`);return true;}
function stopScanner(){if(state.scanner_stream){state.scanner_stream.getTracks().forEach(track=>track.stop());state.scanner_stream=null;}const video=byId('scannerVideo');if(video)video.srcObject=null;}
async function scanWorkEntityCode(){if(!navigator.mediaDevices?.getUserMedia||typeof BarcodeDetector==='undefined'){const code=prompt('Сканирование камерой недоступно. Введите код позиции:');if(code)await findWorkEntityByCode(code);return;}const dialog=byId('scannerDialog'),video=byId('scannerVideo'),status=byId('scannerStatus');try{state.scanner_stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=state.scanner_stream;dialog?.showModal();const detector=new BarcodeDetector({formats:['qr_code','code_128','code_39','ean_13','ean_8','data_matrix']});const started=Date.now();const detect=async()=>{if(!state.scanner_stream||dialog?.open===false)return;try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue||'';status.textContent=`Найден код: ${value}`;stopScanner();dialog?.close();byId('workEntityCode').value=value;await findWorkEntityByCode(value);return;}}catch(e){}if(Date.now()-started>45000){status.textContent='Код не найден. Попробуйте поднести камеру ближе.';}setTimeout(detect,350);};detect();}catch(error){stopScanner();showNotice('Камера недоступна. Введите код вручную.',true);}}

function selectedWorkEntity(){const item=workAccessItem();return (item?.entities||[]).find(x=>String(x.id)===String(val('workEntity')))||null;}
function currentWorkBody(){const item=workAccessItem(),selected=selectedWorkEntity(),amount=qty('workQuantity');if(!item||!selected||!amount||amount<=0)return null;const movement=['movement','transfer_to_assembly'].includes(item.operation_key);const body={chat_id:Number(chatId),user_id:Number(userId),operation_type:item.operation_key,entity_type:selected.type,entity_id:Number(selected.id),quantity:amount,unit:selected.unit||'шт',note:val('workNote'),preset_id:state.active_preset_id||null,client_request_id:state.active_queue_request_id||'',task_id:state.active_task_id||null,lot_id:val('workLot')?Number(val('workLot')):null};if(movement){body.from_area_id=val('workFromArea')?Number(val('workFromArea')):null;body.to_area_id=val('workToArea')?Number(val('workToArea')):null;}else body.area_id=val('workArea')?Number(val('workArea')):null;return body;}
function operationSecondaryText(item){const area=item.from_area_name&&item.to_area_name?`${item.from_area_name} → ${item.to_area_name}`:(item.area_name||'Общий склад');return `${operationLabels[item.operation_type]||item.operation_type} · ${fmt(item.quantity||0)} ${item.unit||'шт'} · ${area}`;}
function applyOperationTemplate(item,presetId=null){if(!item)return;const op=String(item.operation_type||'');if(![...byId('workOperation').options].some(x=>x.value===op)){showNotice('Это действие сейчас недоступно.',true);return;}byId('workOperation').value=op;updateWorkEntry();if([...byId('workEntity').options].some(x=>x.value===String(item.entity_id)))byId('workEntity').value=String(item.entity_id);else{showNotice('Позиция больше не доступна.',true);return;}if(item.area_id)byId('workArea').value=String(item.area_id);if(item.from_area_id)byId('workFromArea').value=String(item.from_area_id);if(item.to_area_id)byId('workToArea').value=String(item.to_area_id);byId('workQuantity').value=Number(item.quantity||0)>0?String(item.quantity):'';byId('workNote').value=item.note||'';const currentEntity=allWorkEntities().find(x=>Number(x.id)===Number(item.entity_id));if(byId('workEntityCode'))byId('workEntityCode').value=currentEntity?.code||'';state.active_preset_id=presetId?Number(presetId):null;saveWorkDraft();updateWorkStockHint();showTab('work');}
function renderOperationShortcuts(){const presetBox=byId('operationPresetList'),recentBox=byId('recentOperationList');if(presetBox){presetBox.innerHTML='';const list=state.operation_presets||[];presetBox.classList.toggle('empty',!list.length);if(!list.length)presetBox.textContent='Закреплённых действий пока нет';list.forEach(item=>{const row=document.createElement('div');row.className='quick-action-card';row.innerHTML=`<div><b>${escapeHtml(item.name)}</b><span>${escapeHtml(operationSecondaryText(item))}</span></div><div class="mini-actions"><button data-use-operation-preset="${item.id}">Заполнить</button><button data-preset-batch="${item.id}">Пакет</button><button class="danger" data-delete-operation-preset="${item.id}">Удалить</button></div>`;presetBox.appendChild(row);});}if(recentBox){recentBox.innerHTML='';const list=state.recent_operations||[];recentBox.classList.toggle('empty',!list.length);if(!list.length)recentBox.textContent='Записей пока нет';list.forEach((item,index)=>{const row=document.createElement('div');row.className='quick-action-card';row.innerHTML=`<div><b>${escapeHtml(item.entity_name||'Позиция')}</b><span>${escapeHtml(operationSecondaryText(item))}</span></div><div class="mini-actions"><button data-use-recent-operation="${index}">Повторить</button></div>`;recentBox.appendChild(row);});}}
function renderSetupHealth(){const box=byId('setupHealthList'),score=byId('setupHealthScore'),health=state.setup_health||{};if(score)score.textContent=health.total?`${health.ready}/${health.total}`:'—';if(!box)return;box.innerHTML='';const checks=health.checks||[];box.classList.toggle('empty',!checks.length);if(!checks.length){box.textContent='Нет данных';return;}checks.forEach(item=>{const row=document.createElement('div');row.className=`setup-check ${item.ok?'ok':'missing'}`;row.textContent=`${item.ok?'✅':'⚠️'} ${item.label}`;box.appendChild(row);});}
function updateWorkStockHint(){const hint=byId('workStockHint'),selected=selectedWorkEntity(),item=workAccessItem();if(!hint)return;if(!selected||!item){hint.textContent='Выберите позицию и площадку';hint.classList.remove('warning');return;}byId('workUnitHint').textContent=selected.unit||'шт';const movement=['movement','transfer_to_assembly'].includes(item.operation_key);const areaId=movement?val('workFromArea'):val('workArea');const row=(state.inventory_positions||[]).find(x=>String(x.entity_id)===String(selected.id)&&String(x.entity_type)===String(selected.type)&&String(x.area_id??'')===String(areaId||''));const amount=qty('workQuantity')||0;const current=Number(row?.quantity||0);const after=operationOutgoing.has(item.operation_key)||movement?current-amount:current+amount;hint.textContent=row?`Сейчас: ${fmt(current)} ${row.unit||selected.unit||'шт'}${amount?` · после: ${fmt(after)}`:''}`:'Текущий остаток не найден для выбранной площадки';hint.classList.toggle('warning',!!row&&after<0);}
function fillPreviewDialog(preview){byId('confirmSummary').textContent=preview.summary||'Проверьте данные';renderRows(byId('confirmBalances'),(preview.balances||[]).map(x=>({name:x.label,value:`${fmt(x.current)} → ${fmt(x.after)} ${x.unit}`})),'');renderRows(byId('confirmComponents'),(preview.components||[]).map(x=>({name:x.name,value:`нужно ${fmt(x.required)}, останется ${fmt(x.after)} ${x.unit}`,flag:Number(x.after)<0?'flag-red':''})),'');const warnings=byId('confirmWarnings');warnings.innerHTML='';(preview.warnings||[]).forEach(x=>{const row=document.createElement('div');row.textContent=`⚠️ ${x}`;warnings.appendChild(row);});warnings.classList.toggle('hidden',!(preview.warnings||[]).length);}
async function startOperationFlow(body){if(state.operation_busy)return;if(!body){showNotice('Выберите действие, позицию и количество.',true);return;}if(['movement','transfer_to_assembly'].includes(body.operation_type)&&(!body.from_area_id||!body.to_area_id)){showNotice('Выберите площадки отправления и получения.',true);return;}body.client_request_id=body.client_request_id||newRequestId();body.confirm_warnings=false;state.pending_queue_index=null;setOperationBusy(true);try{const res=await apiFetch('/api/operations/preview',{method:'POST',headers,body:JSON.stringify(body)});const data=await res.json().catch(()=>({}));if(!res.ok){showNotice(typeof data.detail==='string'?data.detail:'Данные не прошли проверку.',true);return;}body.preview_fingerprint=data.preview?.fingerprint||'';state.pending_operation={body,preview:data.preview||{}};fillPreviewDialog(data.preview||{});const dialog=byId('operationConfirmDialog');if(dialog?.showModal)dialog.showModal();else if(confirm((data.preview?.summary||'Сохранить запись?')+'\n'+(data.preview?.warnings||[]).join('\n')))await submitPendingOperation();}catch(error){if(!navigator.onLine||String(error.message||'').includes('связ'))enqueueOperation(body,'Связи нет — запись добавлена в очередь.');else showNotice(error.message||'Проверка недоступна.',true);}finally{setOperationBusy(false);}}
async function submitPendingOperation(){if(state.operation_busy||!state.pending_operation)return;const original=state.pending_operation;const body={...original.body,confirm_warnings:true,preview_fingerprint:original.preview?.fingerprint||original.body.preview_fingerprint||''};if(state.pending_queue_index!==null&&state.pending_queue_index!==undefined){const queued=state.operation_queue[Number(state.pending_queue_index)];if(queued){queued.body={...body};queued.status='pending';queued.last_error='';persistOperationQueue();}state.pending_operation=null;state.pending_queue_index=null;byId('operationConfirmDialog')?.close();await syncOperationQueue(false);return;}let keepPending=false;setOperationBusy(true);try{const res=await apiFetch('/api/operations',{method:'POST',headers,body:JSON.stringify(body)});const data=await res.json().catch(()=>({}));if(!res.ok){const detail=data.detail;if(detail?.preview){body.preview_fingerprint=detail.preview.fingerprint||'';state.pending_operation={body,preview:detail.preview};fillPreviewDialog(detail.preview);keepPending=true;showNotice(detail.message||'Данные изменились. Проверьте ещё раз.',true);}else showNotice(typeof detail==='string'?detail:(detail?.message||'Запись не сохранена.'),true);return;}state.dashboard=data.dashboard||state.dashboard;state.recent_operations=data.recent_operations||state.recent_operations;state.operation_presets=data.operation_presets||state.operation_presets;state.inventory_positions=data.inventory_positions||state.inventory_positions;state.workflow=data.workflow||state.workflow;renderDashboard(state.dashboard||{});renderOperationShortcuts();renderWorkflow();updateWorkStockHint();if(state.pending_queue_index!==null&&state.pending_queue_index!==undefined){state.operation_queue.splice(Number(state.pending_queue_index),1);persistOperationQueue();}clearWorkDraft(true);byId('operationConfirmDialog')?.close();showNotice(data.duplicate?'Запись уже была сохранена ранее.':`Сохранено${data.operation_id?` · №${data.operation_id}`:''}.`);try{tg?.HapticFeedback?.notificationOccurred?.('success');}catch(e){}await loadAudit();}catch(error){if(!navigator.onLine||String(error.message||'').includes('связ')){if(state.pending_queue_index!==null&&state.pending_queue_index!==undefined){const queued=state.operation_queue[Number(state.pending_queue_index)];if(queued){queued.body={...body,confirm_warnings:true};queued.status='pending';queued.last_error='Нет связи — будет отправлено позже';persistOperationQueue();showNotice('Связи нет — запись осталась в очереди.');}}else enqueueOperation(body,'Связи нет — подтверждённая запись добавлена в очередь.',true);byId('operationConfirmDialog')?.close();}else showNotice(error.message||'Запись не сохранена.',true);}finally{if(!keepPending){state.pending_operation=null;state.pending_queue_index=null;}setOperationBusy(false);}}
async function saveCurrentPreset(){const body=currentWorkBody();if(!body){showNotice('Сначала заполните действие, позицию и количество.',true);return;}const suggested=`${operationLabels[body.operation_type]||'Действие'} · ${selectedWorkEntity()?.name||''}`;const name=window.prompt('Название быстрого действия',suggested);if(!name)return;try{const res=await apiFetch('/api/operation-presets',{method:'POST',headers,body:JSON.stringify({...body,name})});const data=await res.json().catch(()=>({}));if(!res.ok){showNotice(data.detail||'Не удалось закрепить действие.',true);return;}state.operation_presets=data.operation_presets||[];renderOperationShortcuts();showNotice(data.message||'Действие закреплено.');}catch(error){showNotice(error.message,true);}}
async function deleteOperationPreset(id){try{const q=new URLSearchParams({chat_id:chatId,user_id:userId,preset_id:id});const res=await apiFetch('/api/operation-presets?'+q.toString(),{method:'DELETE',headers});const data=await res.json().catch(()=>({}));if(!res.ok){showNotice(data.detail||'Не удалось удалить.',true);return;}state.operation_presets=data.operation_presets||[];renderOperationShortcuts();showNotice(data.message||'Удалено.');}catch(error){showNotice(error.message,true);}}
function can(section){ if(!section) return true; const p=state.permissions||{}; return !!(p[section] || p.setup || p.permissions || p.grant); }
function typeSum(items, names){return (items || []).filter(x => names.includes(x.type)).reduce((s,x)=>s+Number(x.qty||0),0);}
function escapeHtml(v){return String(v ?? '').replace(/[&<>"]/g, s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[s]));}
function renderRows(el, rows, empty='Нет данных'){
  if(!el) return; el.innerHTML = '';
  if(!rows || !rows.length){ el.textContent = empty; el.classList.add('empty'); return; }
  el.classList.remove('empty');
  rows.forEach(r=>{const node=document.createElement('div'); node.className='row '+(r.flag||''); node.innerHTML=`<b>${escapeHtml(r.name)}</b><span>${escapeHtml(r.value)}</span>`; el.appendChild(node);});
}
function showNotice(text, bad=false){const n=byId('notice'); if(!n)return; n.textContent=text; n.className='notice'+(bad?' bad':''); setTimeout(()=>n.classList.add('hidden'), 4200);}
function showTab(tab){
  const target = byId(`page-${tab}`); if(target?.classList.contains('hidden-by-access')){showNotice('Раздел недоступен.', true); return;}
  document.querySelectorAll('.tab,.card[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
  document.querySelectorAll('.tab-page').forEach(x=>x.classList.toggle('active',x.id===`page-${tab}`));
  document.querySelectorAll('.mobile-nav [data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
  document.querySelector('.tabs')?.classList.remove('mobile-open');
  localStorage.setItem('prodMiniTab', tab);
}
function optionList(list, empty='Не выбрано'){return `<option value="">${escapeHtml(empty)}</option>`+(list||[]).map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');}
function fillSelect(id, list, empty){const el=byId(id); if(!el)return; const previous=el.value; el.innerHTML=optionList(list, empty); if([...el.options].some(x=>x.value===previous))el.value=previous;}
function entity(type){return state.entities?.[type] || [];}
function entityTypeById(id){ if(entity('component').some(x=>String(x.id)===String(id))) return 'component'; if(entity('stock_item').some(x=>String(x.id)===String(id))) return 'stock_item'; return 'component';}
function areaChoices(section, action='view'){
  const access=state.area_access?.[section]||{};
  if(!access.restricted) return state.areas||[];
  const allowed=new Set((access[action]||[]).map(String));
  return (state.areas||[]).filter(x=>allowed.has(String(x.id)));
}
function workAccessItem(){return (state.work_access||[]).find(x=>x.operation_key===val('workOperation'))||null;}
function renderWorkEntry(){
  const access=state.work_access||[];
  const tab=document.querySelector('[data-work-entry]');
  tab?.classList.toggle('hidden',!access.length);
  document.querySelector('[data-mobile-work]')?.classList.toggle('hidden',!access.length);
  fillSelect('workOperation',access.map(x=>({id:x.operation_key,name:operationLabels[x.operation_key]||x.operation_key})),'Действие');
  if(access.length && !val('workOperation')) byId('workOperation').value=access[0].operation_key;
  updateWorkEntry();
}
function updateWorkEntry(){
  const item=workAccessItem();const previous=val('workEntity');const search=String(val('workEntitySearch')).trim().toLowerCase();
  const items=(item?.entities||[]).filter(x=>!search||String(x.name||'').toLowerCase().includes(search)||String(x.code||'').toLowerCase().includes(search));
  fillSelect('workEntity',items.map(x=>({id:x.id,name:x.code?`${x.name} · ${x.code}`:x.name})),'Позиция');
  if(previous&&[...byId('workEntity').options].some(x=>x.value===previous))byId('workEntity').value=previous;
  const movement=['movement','transfer_to_assembly'].includes(item?.operation_key||'');
  byId('workSingleArea')?.classList.toggle('hidden',movement);
  byId('workMoveAreas')?.classList.toggle('hidden',!movement);
  state.active_preset_id=null;updateWorkLotChoices();updateWorkStockHint();
}
async function saveWorkEntry(){const body=currentWorkBody();if(!navigator.onLine){enqueueOperation(body,'Связи нет — запись добавлена в очередь.');return;}await startOperationFlow(body);}
function updateMoveEntities(){const t=byId('moveType')?.value||'component'; fillSelect('moveEntity', entity(t), 'Позиция');}
function destinationsByType(types){const allowed=new Set(types); return (state.destinations||[]).filter(x=>allowed.has(x.destination_type));}
function destinationName(id){return (state.destinations||[]).find(x=>String(x.id)===String(id))?.name||'';}
function updateShipDestinations(){
  const kind=val('shipKind');
  const type=kind==='shipment_fulfillment'?'fulfillment':'client';
  fillSelect('shipDestination', destinationsByType([type]), type==='client'?'Клиент не выбран':'Фулфилмент не выбран');
}
function applyAccess(){
  document.querySelectorAll('[data-section]').forEach(el=>{ el.classList.toggle('hidden-by-access', !can(el.dataset.section)); });
  const active = document.querySelector('.tab-page.active');
  if(active?.classList.contains('hidden-by-access')) showTab((state.work_access||[]).length?'work':'overview');
  if((state.work_access||[]).length && localStorage.getItem('prodMiniTab')==='overview') showTab('work');
  const allowed = Object.keys(state.permissions||{}).filter(k=>state.permissions[k]);
  const restricted = Object.values(state.area_access||{}).some(x=>x?.restricted);
  byId('rolePill').textContent = restricted ? 'Доступ по площадкам' : (allowed.length ? 'Доступ настроен' : 'Ограниченный доступ');

  document.querySelectorAll('[data-admin-only]').forEach(el=>el.classList.toggle('hidden',!state.is_system_admin));
  document.querySelectorAll('[data-department-manage]').forEach(el=>el.classList.toggle('hidden',!state.can_manage_departments));
  const canControl=!!(state.is_system_admin||state.can_manage_departments);
  document.querySelectorAll('[data-control-only]').forEach(el=>el.classList.toggle('hidden',!canControl));
  document.querySelectorAll('[data-workflow-manager]').forEach(el=>el.classList.toggle('hidden',!canControl));
  if(state.workspace?.label) byId('rolePill').textContent=state.workspace.label;
  const departmentMode=!state.is_system_admin && (state.department_memberships||[]).length>0;
  document.querySelector('[data-tab="overview"]')?.classList.toggle('hidden',departmentMode);
  document.querySelector('.mobile-nav [data-tab="overview"]')?.classList.toggle('hidden',departmentMode);
  document.querySelector('.summary-grid')?.classList.toggle('hidden',departmentMode);
  if(departmentMode){
    document.querySelectorAll('.tab[data-section]').forEach(el=>{
      const keep=(el.dataset.tab==='inventory' && can('stock')) || el.dataset.tab==='risks';
      el.classList.toggle('hidden-by-access',!keep);
    });
    document.querySelectorAll('.card[data-section]').forEach(el=>el.classList.add('hidden-by-access'));
  }
  applyRiskEventAccess();
}

const shiftPackageStatusLabels={received:'получен',review:'нужна проверка',partial:'частично принят',accepted:'принят',rejected:'отклонён'};
const shiftItemStatusLabels={received:'получена',accepted:'принята',duplicate:'уже была сохранена',review:'нужна проверка',rejected:'отклонена',error:'ошибка'};
function operationEntityName(body){const all=Object.values(state.entities||{}).flat();return all.find(x=>Number(x.id)===Number(body?.entity_id))?.name||body?.entity_name||`Позиция #${body?.entity_id||''}`;}
function renderPackageFilterOptions(){
  const saved={worker:val('packageFilterWorker'),department:val('packageFilterDepartment'),area:val('packageFilterArea'),status:val('packageFilterStatus')};
  const workers=[...new Map((state.shift_packages||[]).map(x=>[String(x.user_id),{id:x.user_id,name:x.worker_name||String(x.user_id)}])).values()];
  fillSelect('packageFilterWorker',workers,'Все доступные');
  fillSelect('packageFilterDepartment',(state.departments||[]).map(x=>({id:x.id,name:x.name})),'Все доступные');
  fillSelect('packageFilterArea',state.areas||[],'Все площадки');
  if(saved.worker&&[...byId('packageFilterWorker')?.options||[]].some(x=>x.value===saved.worker))byId('packageFilterWorker').value=saved.worker;
  if(saved.department&&[...byId('packageFilterDepartment')?.options||[]].some(x=>x.value===saved.department))byId('packageFilterDepartment').value=saved.department;
  if(saved.area&&[...byId('packageFilterArea')?.options||[]].some(x=>x.value===saved.area))byId('packageFilterArea').value=saved.area;
  if(saved.status&&byId('packageFilterStatus'))byId('packageFilterStatus').value=saved.status;
  byId('shiftPackageFilters')?.classList.toggle('hidden',!(state.is_system_admin||state.can_manage_departments));
  byId('packageBulkActions')?.classList.toggle('hidden',!(state.is_system_admin||state.can_manage_departments));
}
function renderShiftPackages(){const box=byId('shiftPackageList');if(!box)return;const list=state.shift_packages||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Пакетов пока нет';renderPackageFilterOptions();return;}list.forEach(pkg=>{const card=document.createElement('div');card.className=`shift-package-card status-${pkg.status||'received'}`;const own=Number(pkg.user_id)===Number(userId);const canReview=!own&&(state.is_system_admin||state.can_manage_departments);const items=(pkg.items||[]).map(item=>{const body=item.payload||{};const reviewable=canReview&&['review','received','error','rejected'].includes(item.status);const selector=reviewable?`<label class="package-select"><input type="checkbox" data-package-select="${item.id}" /> выбрать</label>`:'';const buttons=reviewable?`<button data-package-item-action="approve" data-package-item-id="${item.id}">Принять</button><button class="danger" data-package-item-action="reject" data-package-item-id="${item.id}">Отклонить</button>`:'';return `<div class="package-item status-${escapeHtml(item.status||'received')}"><div>${selector}<b>${escapeHtml(operationEntityName(body))} · ${escapeHtml(fmt(body.quantity))} ${escapeHtml(body.unit||'')}</b><span>${escapeHtml(operationLabels[body.operation_type]||body.operation_type||'Операция')} · ${escapeHtml(shiftItemStatusLabels[item.status]||item.status)}</span>${item.message?`<small>${escapeHtml(item.message)}</small>`:''}</div><div class="mini-actions">${buttons}</div></div>`;}).join('');card.innerHTML=`<div class="package-head"><div><b>${escapeHtml(pkg.worker_name||String(pkg.user_id))}</b><span>${escapeHtml(pkg.area_name||'Без площадки')} · ${escapeHtml(String(pkg.updated_at||pkg.submitted_at||'').slice(0,16))}</span></div><strong>${escapeHtml(shiftPackageStatusLabels[pkg.status]||pkg.status)}</strong></div><small>Всего ${Number(pkg.item_count||0)}, принято ${Number(pkg.accepted_count||0)}, проверить ${Number(pkg.review_count||0)}, отклонено ${Number(pkg.rejected_count||0)}</small><div class="package-items">${items||'<span>Записей нет</span>'}</div>`;box.appendChild(card);});renderPackageFilterOptions();}
async function refreshShiftPackages(){try{const q=new URLSearchParams({chat_id:String(chatId),user_id:String(userId)});if(val('packageFilterWorker'))q.set('worker_user_id',val('packageFilterWorker'));if(val('packageFilterDepartment'))q.set('department_id',val('packageFilterDepartment'));if(val('packageFilterArea'))q.set('area_id',val('packageFilterArea'));if(val('packageFilterStatus'))q.set('status',val('packageFilterStatus'));if(val('packageFilterFrom'))q.set('date_from',val('packageFilterFrom'));if(val('packageFilterTo'))q.set('date_to',val('packageFilterTo'));const res=await apiFetch(`/api/shift-packages?${q.toString()}`,{headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Пакеты недоступны.');state.shift_packages=data.shift_packages||[];renderShiftPackages();}catch(e){showNotice(e.message||'Не удалось обновить пакеты.',true);}}
async function bulkReviewShiftPackages(action){const ids=[...document.querySelectorAll('[data-package-select]:checked')].map(x=>Number(x.dataset.packageSelect)).filter(Boolean);if(!ids.length){showNotice('Отметьте записи для обработки.',true);return;}let note='';if(action==='reject'){note=prompt('Общая причина отклонения выбранных записей:','Требуется исправление')||'';if(!note)return;}if(!confirm(`${action==='approve'?'Принять':'Отклонить'} выбранных записей: ${ids.length}?`))return;try{const res=await apiFetch('/api/shift-packages/bulk-action',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),item_ids:ids,action,note})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Записи не обработаны.');state.shift_packages=data.shift_packages||[];renderShiftPackages();showNotice(data.message||'Готово.');if((data.failed||[]).length)showNotice(`Не обработано: ${data.failed.length}. Проверьте записи.`,true);}catch(e){showNotice(e.message||'Не удалось обработать записи.',true);}}
function clearPackageFilters(){['packageFilterWorker','packageFilterDepartment','packageFilterArea','packageFilterStatus','packageFilterFrom','packageFilterTo'].forEach(id=>{if(byId(id))byId(id).value='';});refreshShiftPackages();}
async function reviewServerPackageItem(itemId,action){let reason='';if(action==='reject'){reason=prompt('Причина отклонения записи:','Требуется исправление')||'';if(!reason)return;}try{const res=await apiFetch('/api/shift-packages/item-action',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),item_id:Number(itemId),action,note:reason})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Запись не обработана.');state.shift_packages=data.shift_packages||state.shift_packages;renderShiftPackages();showNotice(data.message||'Запись обработана.');}catch(e){showNotice(e.message||'Ошибка обработки.',true);}}
function renderHandoverChecklist(){const box=byId('handoverChecklist');if(!box)return;const list=state.handover_checklist||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.innerHTML='<small>Чек-лист не настроен. Можно передать смену по комментарию.</small>';return;}list.forEach(item=>{const row=document.createElement('div');row.className='handover-check-row';row.innerHTML=`<label class="check-line"><input type="checkbox" data-handover-check="${item.item_id}" data-required="${item.required?1:0}" /> ${item.required?'<b>*</b> ':''}${escapeHtml(item.label)}</label><input data-handover-note="${item.item_id}" maxlength="500" placeholder="Замечание к пункту — необязательно" />`;box.appendChild(row);});}
function handoverChecklistPayload(){return (state.handover_checklist||[]).map(item=>({item_id:Number(item.item_id),label:item.label,required:!!item.required,checked:!!document.querySelector(`[data-handover-check="${item.item_id}"]`)?.checked,note:document.querySelector(`[data-handover-note="${item.item_id}"]`)?.value||''}));}
function renderShiftHandovers(){const box=byId('shiftHandoverList');if(!box)return;const list=state.shift_handovers||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Передач пока нет';return;}list.forEach(item=>{const canAck=item.status==='open'&&(item.to_user_id==null||Number(item.to_user_id)===Number(userId)||state.can_manage_departments||state.is_system_admin);const checks=(item.checklist||[]).map(x=>`<small>${x.is_checked?'✓':'○'} ${escapeHtml(x.label)}${x.note?` — ${escapeHtml(x.note)}`:''}</small>`).join('');const row=document.createElement('div');row.className=`manager-row handover-${item.status}`;row.innerHTML=`<div><b>${escapeHtml(item.from_name||item.from_user_id)} → ${escapeHtml(item.to_name||'следующей смене')}</b><span>${escapeHtml(item.area_name||'Без площадки')} · ${escapeHtml(String(item.created_at||'').slice(0,16))}</span><small>${escapeHtml(item.summary||'Без примечания')}</small><small>Незавершённых пакетов: ${Number(item.unfinished_count||0)}, проблемных записей: ${Number(item.issue_count||0)}${Number(item.checklist_total||0)?` · чек-лист ${Number(item.checklist_done||0)}/${Number(item.checklist_total||0)}`:''}</small>${checks}</div><div class="mini-actions">${canAck?`<button data-ack-handover="${item.id}">Принять</button>`:'<span>Принято</span>'}</div>`;box.appendChild(row);});}
async function createShiftHandover(){const summary=val('handoverSummary').trim();const checklist=handoverChecklistPayload();const missing=checklist.filter(x=>x.required&&!x.checked);if(missing.length){showNotice(`Отметьте обязательные пункты: ${missing.map(x=>x.label).slice(0,3).join(', ')}`,true);return;}if(!summary&&!checklist.length&&!confirm('Передать смену без комментария?'))return;try{const res=await apiFetch('/api/shift-handovers',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),to_user_id:val('handoverToWorker')?Number(val('handoverToWorker')):null,shift_id:state.current_open_shift?.id?Number(state.current_open_shift.id):null,area_id:val('handoverArea')?Number(val('handoverArea')):null,summary,package_ids:[],checklist})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Передача не сохранена.');state.shift_handovers=data.shift_handovers||[];byId('handoverSummary').value='';renderHandoverChecklist();renderShiftHandovers();showNotice(data.message||'Смена передана.');}catch(e){showNotice(e.message||'Передача не сохранена.',true);}}
async function acknowledgeHandover(id){try{const res=await apiFetch('/api/shift-handovers/acknowledge',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),handover_id:Number(id)})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Передача недоступна.');state.shift_handovers=data.shift_handovers||[];renderShiftHandovers();showNotice(data.message||'Передача принята.');}catch(e){showNotice(e.message||'Не удалось принять передачу.',true);}}
function renderMiniappDevices(){const box=byId('miniappDeviceList');if(!box)return;const list=state.miniapp_devices||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Устройства ещё не зарегистрированы';return;}list.forEach(item=>{const current=String(item.device_id)===String(deviceId);const revoked=!!item.revoked_at;const canRestore=revoked&&state.is_system_admin;const canRevoke=!revoked&&(Number(item.user_id)===Number(userId)||state.is_system_admin);const row=document.createElement('div');row.className=`manager-row device-row ${revoked?'revoked':''}`;row.innerHTML=`<div><b>${escapeHtml(item.device_name||item.platform||'Устройство')}${current?' · это устройство':''}</b><span>Пользователь ${escapeHtml(item.user_id)} · ${escapeHtml(item.platform||'')}</span><small>Последняя активность: ${escapeHtml(String(item.last_seen_at||'').slice(0,16))}${revoked?' · доступ отозван':''}</small></div><div class="mini-actions">${canRevoke?`<button class="danger" data-device-action="revoke" data-device-user="${item.user_id}" data-device-id="${escapeHtml(item.device_id)}">Отозвать</button>`:''}${canRestore?`<button data-device-action="restore" data-device-user="${item.user_id}" data-device-id="${escapeHtml(item.device_id)}">Восстановить</button>`:''}</div>`;box.appendChild(row);});}
async function changeDeviceAccess(action,targetUserId,targetDeviceId){if(action==='revoke'&&String(targetDeviceId)===String(deviceId)&&!confirm('Отозвать доступ у текущего устройства? Mini App сразу перестанет работать на нём.'))return;try{const res=await apiFetch('/api/devices/action',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),target_user_id:Number(targetUserId),device_id:String(targetDeviceId),action,reason:action==='revoke'?'Отозвано через Mini App':''})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Действие не выполнено.');state.miniapp_devices=data.miniapp_devices||[];renderMiniappDevices();showNotice(data.message||'Готово.');}catch(e){showNotice(e.message||'Не удалось изменить доступ.',true);}}
function selectedLabelEntityIds(all=false){const nodes=[...document.querySelectorAll('[data-label-entity]')];return [...new Set(nodes.filter(x=>all||x.checked).map(x=>Number(x.dataset.labelEntity)).filter(Boolean))];}
function renderLabelTemplates(){const list=state.label_templates||[];fillSelect('entityLabelTemplate',list.map(x=>({id:x.id,name:`${x.name}${x.is_default?' · по умолчанию':''}`})),'Стандартный A4');const def=list.find(x=>x.is_default);if(def&&byId('entityLabelTemplate')&&!byId('entityLabelTemplate').value)byId('entityLabelTemplate').value=String(def.id);}
async function printEntityLabels(all=false){const ids=selectedLabelEntityIds(all);if(!ids.length){showNotice('Отметьте позиции для печати.',true);return;}const q=new URLSearchParams({chat_id:chatId,user_id:userId,entity_ids:ids.join(','),code_type:val('entityLabelType')||'qr',copies:String(Math.max(1,Number(val('entityLabelCopies')||1)))});if(val('entityLabelTemplate'))q.set('template_id',val('entityLabelTemplate'));try{const res=await apiFetch('/api/entity-labels?'+q.toString(),{headers},60000);if(!res.ok){const data=await res.json().catch(()=>({}));throw new Error(data.detail||'Этикетки не созданы.');}await downloadBlob(res,`entity_labels_${new Date().toISOString().slice(0,10)}.pdf`);showNotice('Этикетки сформированы.');}catch(e){showNotice(e.message||'Этикетки не созданы.',true);}}
async function saveLabelTemplate(){const body={chat_id:Number(chatId),user_id:Number(userId),name:val('labelTemplateName').trim(),page_mode:val('labelTemplatePageMode')||'a4',label_width_mm:Number(val('labelTemplateWidth')||63),label_height_mm:Number(val('labelTemplateHeight')||32),columns_count:Number(val('labelTemplateCols')||3),rows_count:Number(val('labelTemplateRows')||8),margin_x_mm:Number(val('labelTemplateMarginX')||8),margin_y_mm:Number(val('labelTemplateMarginY')||8),gap_x_mm:Number(val('labelTemplateGapX')||3),gap_y_mm:Number(val('labelTemplateGapY')||3),code_size_mm:Number(val('labelTemplateCodeSize')||21),code_type:val('entityLabelType')||'qr',is_default:!!byId('labelTemplateDefault')?.checked};if(!body.name){showNotice('Введите название шаблона.',true);return;}try{const res=await apiFetch('/api/label-templates',{method:'POST',headers,body:JSON.stringify(body)});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Шаблон не сохранён.');state.label_templates=data.label_templates||[];renderLabelTemplates();showNotice(data.message||'Шаблон сохранён.');}catch(e){showNotice(e.message||'Шаблон не сохранён.',true);}}

function renderContinuitySettings(){const x=state.continuity_settings||{};[['continuityPackageFirst','package_reminder_after_minutes',60],['continuityPackageRepeat','package_repeat_minutes',120],['continuityHandoverFirst','handover_reminder_after_minutes',30],['continuityHandoverRepeat','handover_repeat_minutes',60],['continuityMaxReminders','max_reminders',3]].forEach(([id,key,def])=>{if(byId(id))byId(id).value=String(x[key]??def);});}
async function saveContinuitySettings(){const body={chat_id:Number(chatId),user_id:Number(userId),package_reminder_after_minutes:Number(val('continuityPackageFirst')||60),package_repeat_minutes:Number(val('continuityPackageRepeat')||120),handover_reminder_after_minutes:Number(val('continuityHandoverFirst')||30),handover_repeat_minutes:Number(val('continuityHandoverRepeat')||60),max_reminders:Number(val('continuityMaxReminders')||3)};try{const res=await apiFetch('/api/continuity/settings',{method:'POST',headers,body:JSON.stringify(body)});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Настройки не сохранены.');state.continuity_settings=data.continuity_settings||{};renderContinuitySettings();showNotice(data.message||'Настройки сохранены.');}catch(e){showNotice(e.message||'Настройки не сохранены.',true);}}
function renderHandoverChecklistEditor(){if(!byId('handoverChecklistEditor'))return;byId('handoverChecklistEditor').value=(state.handover_checklist||[]).map(x=>`${x.required?'':'? '}${x.label}`).join('\n');renderHandoverChecklist();}
async function saveHandoverChecklist(){const lines=val('handoverChecklistEditor').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,40);const items=lines.map(line=>({label:line.startsWith('?')?line.slice(1).trim():line,required:!line.startsWith('?')})).filter(x=>x.label);try{const res=await apiFetch('/api/continuity/checklist',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),name:'Основной чек-лист',items})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Чек-лист не сохранён.');state.handover_checklist=data.handover_checklist||[];renderHandoverChecklistEditor();showNotice(data.message||'Чек-лист сохранён.');}catch(e){showNotice(e.message||'Чек-лист не сохранён.',true);}}
async function downloadContinuityAudit(){const q=new URLSearchParams({chat_id:String(chatId),user_id:String(userId)});try{const res=await apiFetch('/api/continuity-audit.xlsx?'+q.toString(),{headers},60000);if(!res.ok){const data=await res.json().catch(()=>({}));throw new Error(data.detail||'Журнал не сформирован.');}await downloadBlob(res,`audit_smen_${new Date().toISOString().slice(0,10)}.xlsx`);showNotice('Журнал аудита сформирован.');}catch(e){showNotice(e.message||'Журнал не сформирован.',true);}}


function allVisibleEntities(){return Object.values(state.entities||{}).flat().map(x=>({...x,name:x.name||`Позиция #${x.id}`}));}
function workflowDepartment(id){return (state.workflow_options?.departments||[]).find(x=>Number(x.id)===Number(id))||null;}
function manageableWorkflowDepartment(id){return (state.workflow_options?.manageable_departments||[]).find(x=>Number(x.id)===Number(id))||null;}
function taskStatusLabel(v){return ({planned:'план',in_progress:'в работе',paused:'пауза',completed:'выполнено',cancelled:'отменено'})[v]||v;}
function requestStatusLabel(v){return ({requested:'запрошено',approved:'подтверждено',issued:'выдано',partially_received:'частично получено',received:'получено',rejected:'отклонено',cancelled:'отменено'})[v]||v;}
function priorityLabel(v){return ({low:'низкий',normal:'обычный',high:'высокий',urgent:'срочный'})[v]||v;}
function renderWorkTaskContext(){const box=byId('workTaskContext');if(!box)return;const task=(state.workflow?.tasks||[]).find(x=>Number(x.id)===Number(state.active_task_id));box.classList.toggle('hidden',!task);if(!task)return;byId('workTaskTitle').textContent=`Задание №${task.id} · ${task.entity_name||''}`;const remain=Math.max(0,Number(task.target_quantity||0)-Number(task.actual_quantity||0));byId('workTaskMeta').textContent=`${taskStatusLabel(task.status)} · план ${fmt(task.target_quantity)} · факт ${fmt(task.actual_quantity)} · осталось ${fmt(remain)} ${task.unit||'шт'}`;}
function updateWorkLotChoices(){const selected=selectedWorkEntity();const list=(state.workflow?.lots||[]).filter(x=>!selected||Number(x.entity_id)===Number(selected.id));fillSelect('workLot',list.map(x=>({id:x.id,name:`${x.lot_code} · ${x.entity_name||''}`})),'Без партии');if(state.active_lot_id&&[...byId('workLot')?.options||[]].some(x=>Number(x.value)===Number(state.active_lot_id)))byId('workLot').value=String(state.active_lot_id);}
function renderWorkflowForms(){
  const opts=state.workflow_options||{};const manageable=opts.manageable_departments||[];const own=opts.own_departments||[];
  fillSelect('wfTaskDepartment',manageable.map(x=>({id:x.id,name:x.name})),'Отдел');
  fillSelect('wfEquipmentDepartment',manageable.map(x=>({id:x.id,name:x.name})),'Отдел');
  fillSelect('wfRequestFromDepartment',own.filter(x=>Number(x.role_level||0)>=20).map(x=>({id:x.id,name:x.name})),'Ваш отдел');
  fillSelect('wfRequestToDepartment',(opts.departments||[]).filter(x=>!own.some(o=>Number(o.id)===Number(x.id))).map(x=>({id:x.id,name:x.name})),'Отдел-поставщик');
  const all=allVisibleEntities();fillSelect('wfTaskEntity',all,'Позиция');fillSelect('wfRequestEntity',all,'Позиция');fillSelect('wfLotEntity',all,'Позиция');
  fillSelect('wfTaskArea',state.areas||[],'Без площадки');fillSelect('wfEquipmentArea',state.areas||[],'Без площадки');fillSelect('wfRequestFromArea',state.areas||[],'Общий склад');fillSelect('wfRequestToArea',state.areas||[],'Общий склад');
  fillSelect('wfTaskOutputLot',(state.workflow?.lots||[]).map(x=>({id:x.id,name:`${x.lot_code} · ${x.entity_name}`})),'Без партии');
  updateWorkflowTaskDepartment();
  const from=byId('wfPlanFactFrom'),to=byId('wfPlanFactTo');if(from&&!from.value){const d=new Date();d.setDate(d.getDate()-7);from.value=d.toISOString().slice(0,10);}if(to&&!to.value)to.value=new Date().toISOString().slice(0,10);
}
function updateWorkflowTaskDepartment(){const depId=Number(val('wfTaskDepartment')||0),dep=manageableWorkflowDepartment(depId);fillSelect('wfTaskAssignee',(dep?.members||[]).map(x=>({id:x.user_id,name:x.display_name||String(x.user_id)})),'Без конкретного исполнителя');const full=(state.departments||[]).find(x=>Number(x.id)===depId);const ops=(full?.operations||[]).filter(x=>x.can_submit).map(x=>({id:x.operation_key,name:operationLabels[x.operation_key]||x.operation_key}));fillSelect('wfTaskOperation',ops,'Действие');const memberIds=new Set((dep?.members||[]).map(x=>Number(x.user_id)));const shifts=(state.shift_plans||[]).filter(x=>['planned','in_progress'].includes(x.status)&&(!memberIds.size||memberIds.has(Number(x.user_id))));fillSelect('wfTaskShift',shifts.map(x=>({id:x.id,name:`${x.worker_name||x.user_id} · ${String(x.planned_start||'').slice(0,16)} — ${String(x.planned_end||'').slice(11,16)}`})),'Без привязки к смене');updateWorkflowTaskEntities();}
function updateWorkflowTaskShift(){const id=Number(val('wfTaskShift')||0);if(!id)return;const shift=(state.shift_plans||[]).find(x=>Number(x.id)===id);if(!shift)return;if(byId('wfTaskAssignee'))byId('wfTaskAssignee').value=String(shift.user_id||'');if(shift.area_id&&byId('wfTaskArea'))byId('wfTaskArea').value=String(shift.area_id);if(shift.planned_end&&byId('wfTaskDue'))byId('wfTaskDue').value=String(shift.planned_end).replace(' ','T').slice(0,16);}
function updateWorkflowTaskEntities(){const depId=Number(val('wfTaskDepartment')||0),op=val('wfTaskOperation');const full=(state.departments||[]).find(x=>Number(x.id)===depId);const rules=(full?.entities||[]).filter(x=>x.operation_key===op&&x.can_submit);const ids=new Set(rules.map(x=>Number(x.entity_id)));const all=allVisibleEntities().filter(x=>ids.has(Number(x.id)));fillSelect('wfTaskEntity',all,'Позиция');}

function renderWorkflow(){const w=state.workflow||{},c=w.counts||{};if(byId('wfActiveTasks'))byId('wfActiveTasks').textContent=String(c.active_tasks||0);if(byId('wfOpenRequests'))byId('wfOpenRequests').textContent=String(c.open_requests||0);if(byId('wfDowntimes'))byId('wfDowntimes').textContent=String(c.downtimes||0);if(byId('wfMaintenance'))byId('wfMaintenance').textContent=String(c.maintenance_due||0);renderWorkflowTasks();renderWorkflowRequests();renderWorkflowLots();renderWorkflowEquipment();renderWorkflowPlanFact(w.plan_fact||{});renderWorkflowForms();renderWorkTaskContext();updateWorkLotChoices();}
function renderWorkflowTasks(){const box=byId('wfTaskList');if(!box)return;const list=state.workflow?.tasks||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Заданий пока нет';return;}list.forEach(t=>{const row=document.createElement('div');row.className=`manager-row workflow-row ${t.priority==='urgent'?'danger-row':''}`;const remain=Math.max(0,Number(t.target_quantity||0)-Number(t.actual_quantity||0));const due=t.due_at?` · срок ${String(t.due_at).slice(0,16)}`:'';const shift=t.shift_plan_id?` · смена ${escapeHtml(t.shift_worker_name||t.shift_user_id||'')} ${escapeHtml(String(t.shift_planned_start||'').slice(0,16))}`:'';let actions=t.can_work?`<button data-task-work="${t.id}">Внести</button>`:'';if(t.can_start)actions+=`<button data-task-action="${t.id}:start">Начать</button>`;if(t.can_pause)actions+=`<button data-task-action="${t.id}:pause">Пауза</button>`;if(t.can_complete)actions+=`<button data-task-action="${t.id}:complete">Готово</button>`;if(t.can_cancel)actions+=`<button class="danger" data-task-action="${t.id}:cancel">Отменить</button>`;if(t.can_reopen)actions+=`<button data-task-action="${t.id}:reopen">Вернуть в план</button>`;row.innerHTML=`<div><b>№${t.id} · ${escapeHtml(t.entity_name)} · ${escapeHtml(taskStatusLabel(t.status))}</b><span>${escapeHtml(t.department_name)}${t.assignee_user_id?` · исполнитель ${escapeHtml(t.assignee_user_id)}`:''}${shift} · план ${escapeHtml(fmt(t.target_quantity))} · факт ${escapeHtml(fmt(t.actual_quantity))} · осталось ${escapeHtml(fmt(remain))} ${escapeHtml(t.unit||'шт')} · приоритет ${escapeHtml(priorityLabel(t.priority))}${escapeHtml(due)}</span></div><div class="mini-actions">${actions}</div>`;box.appendChild(row);});}
function renderWorkflowRequests(){const box=byId('wfRequestList');if(!box)return;const list=state.workflow?.requests||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Заявок пока нет';return;}list.forEach(r=>{const row=document.createElement('div');row.className=`manager-row workflow-row ${r.priority==='urgent'?'danger-row':''}`;let actions='';if(r.can_approve)actions+=`<button data-request-action="${r.id}:approve">Подтвердить</button>`;if(r.can_reject)actions+=`<button class="danger" data-request-action="${r.id}:reject">Отклонить</button>`;if(r.can_issue)actions+=`<button data-request-action="${r.id}:issue">Выдать</button>`;if(r.can_receive)actions+=`<button data-request-action="${r.id}:receive">Получить</button>`;if(r.can_cancel)actions+=`<button data-request-action="${r.id}:cancel">Отменить</button>`;row.innerHTML=`<div><b>№${r.id} · ${escapeHtml(r.entity_name)} · ${escapeHtml(requestStatusLabel(r.status))}</b><span>${escapeHtml(r.requester_department_name)} → ${escapeHtml(r.supplier_department_name)} · запрос ${escapeHtml(fmt(r.requested_quantity))} · выдано ${escapeHtml(fmt(r.issued_quantity))} · получено ${escapeHtml(fmt(r.received_quantity))} ${escapeHtml(r.unit||'шт')}${r.needed_at?` · нужно к ${escapeHtml(String(r.needed_at).slice(0,16))}`:''}</span></div><div class="mini-actions">${actions}</div>`;box.appendChild(row);});}
function renderWorkflowLots(){const box=byId('wfLotList');if(!box)return;const list=state.workflow?.lots||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Партий пока нет';return;}list.forEach(x=>{const row=document.createElement('div');row.className='manager-row';row.innerHTML=`<div><b>${escapeHtml(x.lot_code)} · ${escapeHtml(x.entity_name)}</b><span>отслеживается ${escapeHtml(fmt(x.tracked_quantity))} · ${escapeHtml(x.area_names||'без площадки')}${x.expiry_date?` · годен до ${escapeHtml(x.expiry_date)}`:''}</span></div><div class="mini-actions"><button data-lot-trace="${x.id}">Проследить</button></div>`;box.appendChild(row);});}
function renderWorkflowEquipment(){const box=byId('wfEquipmentList');if(!box)return;const list=state.workflow?.equipment||[];box.innerHTML='';box.classList.toggle('empty',!list.length);if(!list.length){box.textContent='Оборудование пока не добавлено';return;}list.forEach(x=>{const row=document.createElement('div');row.className=`manager-row workflow-row ${Number(x.open_downtimes||0)>0?'danger-row':''}`;let actions='';if(Number(x.open_downtimes||0)>0&&x.can_close_downtime)actions+=`<button data-equipment-close="${x.id}">Закрыть простой</button>`;else if(Number(x.open_downtimes||0)===0&&x.can_report_downtime)actions+=`<button data-equipment-down="${x.id}">Простой</button>`;if(x.can_maintain)actions+=`<button data-equipment-maintenance="${x.id}">ТО выполнено</button>`;row.innerHTML=`<div><b>${escapeHtml(x.name)} · ${escapeHtml(x.status)}</b><span>${escapeHtml(x.department_name||'Без отдела')} · ${escapeHtml(x.area_name||'без площадки')}${x.next_service_at?` · следующее ТО ${escapeHtml(String(x.next_service_at).slice(0,10))}`:''}${Number(x.open_downtimes||0)>0?' · ЕСТЬ ПРОСТОЙ':''}</span></div><div class="mini-actions">${actions}</div>`;box.appendChild(row);});}
function renderWorkflowPlanFact(pf){const box=byId('wfPlanFactList');if(!box)return;const deps=pf?.departments||[],shifts=pf?.shifts||[];box.innerHTML='';box.classList.toggle('empty',!deps.length&&!shifts.length);if(!deps.length&&!shifts.length){box.textContent='Нет данных';return;}if(deps.length){const h=document.createElement('div');h.className='section-mini-title';h.textContent='По отделам';box.appendChild(h);deps.forEach(x=>{const row=document.createElement('div');row.className=`manager-row ${Number(x.overdue||0)>0?'danger-row':''}`;row.innerHTML=`<div><b>${escapeHtml(x.department_name)} · ${escapeHtml(fmt(x.completion_percent))}%</b><span>заданий ${x.tasks} · план ${escapeHtml(fmt(x.target))} · факт ${escapeHtml(fmt(x.actual))} · отклонение ${escapeHtml(fmt(x.deviation))} · выполнено ${x.completed} · просрочено ${x.overdue} · простой ${escapeHtml(fmt(x.downtime_minutes))} мин</span></div>`;box.appendChild(row);});}if(shifts.length){const h=document.createElement('div');h.className='section-mini-title';h.textContent='По плановым сменам';box.appendChild(h);shifts.forEach(x=>{const row=document.createElement('div');row.className=`manager-row ${Number(x.overdue||0)>0?'danger-row':''}`;row.innerHTML=`<div><b>${escapeHtml(x.worker_name||'Сотрудник')} · ${escapeHtml(String(x.planned_start||'').slice(0,16))} · ${escapeHtml(fmt(x.completion_percent))}%</b><span>${escapeHtml(x.department_name||'')} · заданий ${x.tasks} · план ${escapeHtml(fmt(x.target))} · факт ${escapeHtml(fmt(x.actual))} · отклонение ${escapeHtml(fmt(x.deviation))}</span></div>`;box.appendChild(row);});}}
async function refreshWorkflow(){try{const q=new URLSearchParams({chat_id:chatId,user_id:userId});const res=await apiFetch('/api/workflow?'+q.toString(),{headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Данные не загружены.');state.workflow=data.workflow||{};state.workflow_options=data.workflow_options||{};renderWorkflow();}catch(e){showNotice(e.message||'Данные не загружены.',true);}}
async function createProductionTask(){const body={chat_id:Number(chatId),user_id:Number(userId),department_id:Number(val('wfTaskDepartment')||0),assignee_user_id:val('wfTaskAssignee')?Number(val('wfTaskAssignee')):null,shift_plan_id:val('wfTaskShift')?Number(val('wfTaskShift')):null,operation_type:val('wfTaskOperation')||'production',entity_id:Number(val('wfTaskEntity')||0),target_quantity:Number(String(val('wfTaskQuantity')).replace(',','.')),unit:allVisibleEntities().find(x=>Number(x.id)===Number(val('wfTaskEntity')))?.unit||'шт',area_id:val('wfTaskArea')?Number(val('wfTaskArea')):null,priority:val('wfTaskPriority')||'normal',due_at:val('wfTaskDue')||null,note:val('wfTaskNote'),output_lot_id:val('wfTaskOutputLot')?Number(val('wfTaskOutputLot')):null};if(!body.department_id||!body.entity_id||!body.target_quantity){showNotice('Выберите отдел, позицию и плановое количество.',true);return;}await workflowPost('/api/production-tasks',body,'Задание создано.');}
async function createDepartmentRequest(){const ent=allVisibleEntities().find(x=>Number(x.id)===Number(val('wfRequestEntity')));const body={chat_id:Number(chatId),user_id:Number(userId),requester_department_id:Number(val('wfRequestFromDepartment')||0),supplier_department_id:Number(val('wfRequestToDepartment')||0),entity_id:Number(val('wfRequestEntity')||0),quantity:Number(String(val('wfRequestQuantity')).replace(',','.')),unit:ent?.unit||'шт',from_area_id:val('wfRequestFromArea')?Number(val('wfRequestFromArea')):null,to_area_id:val('wfRequestToArea')?Number(val('wfRequestToArea')):null,priority:val('wfRequestPriority')||'normal',needed_at:val('wfRequestNeeded')||null,note:val('wfRequestNote')};if(!body.requester_department_id||!body.supplier_department_id||!body.entity_id||!body.quantity){showNotice('Заполните отделы, позицию и количество.',true);return;}await workflowPost('/api/department-requests',body,'Заявка создана.');}
async function createProductionLot(){const body={chat_id:Number(chatId),user_id:Number(userId),entity_id:Number(val('wfLotEntity')||0),lot_code:val('wfLotCode').trim(),supplier_code:val('wfLotSupplier').trim(),manufacture_date:val('wfLotManufacture')||null,expiry_date:val('wfLotExpiry')||null,note:val('wfLotNote')};if(!body.entity_id||!body.lot_code){showNotice('Выберите позицию и укажите код партии.',true);return;}await workflowPost('/api/lots',body,'Партия создана.');}
async function saveWorkflowEquipment(){const body={chat_id:Number(chatId),user_id:Number(userId),department_id:val('wfEquipmentDepartment')?Number(val('wfEquipmentDepartment')):null,area_id:val('wfEquipmentArea')?Number(val('wfEquipmentArea')):null,name:val('wfEquipmentName').trim(),code:val('wfEquipmentCode').trim(),service_interval_days:Number(val('wfEquipmentInterval')||0),warning_before_days:Number(val('wfEquipmentWarning')||3),note:val('wfEquipmentNote')};if(!body.name){showNotice('Введите название оборудования.',true);return;}await workflowPost('/api/equipment',body,'Оборудование сохранено.');}
async function workflowPost(url,body,okText){try{const res=await apiFetch(url,{method:'POST',headers,body:JSON.stringify(body)});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(typeof data.detail==='string'?data.detail:(data.detail?.message||'Действие не выполнено.'));if(data.workflow)state.workflow=data.workflow;renderWorkflow();showNotice(data.message||okText);}catch(e){showNotice(e.message||'Действие не выполнено.',true);}}
async function workflowTaskAction(id,action){let reason='';if(action==='cancel')reason=prompt('Причина отмены:')||'';if(action==='complete'){const task=(state.workflow?.tasks||[]).find(x=>Number(x.id)===Number(id));if(task&&Math.abs(Number(task.actual_quantity||0)-Number(task.target_quantity||0))>1e-9)reason=prompt('Факт отличается от плана. Укажите причину отклонения:')||'';}await workflowPost('/api/production-tasks/action',{chat_id:Number(chatId),user_id:Number(userId),task_id:Number(id),action,reason},'Задание обновлено.');}
function useWorkflowTask(id){const task=(state.workflow?.tasks||[]).find(x=>Number(x.id)===Number(id));if(!task)return;const access=(state.work_access||[]).find(x=>x.operation_key===task.operation_type&&(x.entities||[]).some(e=>Number(e.id)===Number(task.entity_id)));if(!access){showNotice('Для этого задания нет разрешённого рабочего действия.',true);return;}state.active_task_id=Number(task.id);byId('workOperation').value=task.operation_type;updateWorkEntry();byId('workEntity').value=String(task.entity_id);if(task.area_id)byId('workArea').value=String(task.area_id);const remain=Math.max(0,Number(task.target_quantity||0)-Number(task.actual_quantity||0));if(remain>0)byId('workQuantity').value=String(remain);if(task.output_lot_id){state.active_lot_id=Number(task.output_lot_id);updateWorkLotChoices();byId('workLot').value=String(task.output_lot_id);}renderWorkTaskContext();updateWorkStockHint();saveWorkDraft();showTab('work');}
async function workflowRequestAction(id,action){let quantity=null,reason='';if(['approve','issue','receive'].includes(action)){const raw=prompt(action==='approve'?'Подтверждённое количество:':action==='issue'?'Количество к выдаче:':'Количество получено:');if(raw===null)return;quantity=Number(String(raw).replace(',','.'));if(!quantity||quantity<=0){showNotice('Введите количество больше нуля.',true);return;}}if(['reject','cancel'].includes(action)){reason=prompt('Укажите причину:')||'';if(action==='reject'&&!reason){showNotice('Причина обязательна.',true);return;}}await workflowPost('/api/department-requests/action',{chat_id:Number(chatId),user_id:Number(userId),request_id:Number(id),action,quantity,reason},'Заявка обновлена.');}
