async function equipmentDowntime(id){const reason=prompt('Причина простоя:');if(!reason)return;await workflowPost('/api/equipment/downtime',{chat_id:Number(chatId),user_id:Number(userId),equipment_id:Number(id),reason_type:'other',reason},'Простой зарегистрирован.');}
