function qualitySupplyData(){return state.quality_supply||{quality:{},replenishment:{},maintenance:{}};}
function renderQualitySupplyForms(){
  const all=allVisibleEntities();const deps=(state.workflow_options?.departments||state.departments||[]).map(x=>({id:x.id,name:x.name}));const manageable=(state.workflow_options?.manageable_departments||state.departments||[]).map(x=>({id:x.id,name:x.name}));
  ['qsInspectionEntity','qsRuleEntity','qsReplenishmentEntity','qsMaintenancePartEntity'].forEach(id=>fillSelect(id,all,'Позиция'));
  fillSelect('qsInspectionDepartment',deps,'Отдел');fillSelect('qsRuleDepartment',manageable,'Без отдела');fillSelect('qsRuleReworkDepartment',manageable,'Тот же отдел');
  fillSelect('qsInspectionArea',state.areas||[],'Без площадки');fillSelect('qsReplenishmentArea',state.areas||[],'Все площадки');fillSelect('qsMaintenancePartArea',state.areas||[],'Склад');
  fillSelect('qsInspectionLot',(state.workflow?.lots||[]).map(x=>({id:x.id,name:`${x.lot_code} · ${x.entity_name}`})),'Без партии');
  fillSelect('qsInspectionTask',(state.workflow?.tasks||[]).filter(x=>['planned','in_progress','paused'].includes(x.status)).map(x=>({id:x.id,name:`№${x.id} · ${x.entity_name}`})),'Без задания');
  fillSelect('qsInspectionEquipment',(state.workflow?.equipment||[]).map(x=>({id:x.id,name:x.name})),'Без оборудования');fillSelect('qsMaintenanceEquipment',(state.workflow?.equipment||[]).map(x=>({id:x.id,name:x.name})),'Оборудование');
  if(byId('qsReportFrom')&&!byId('qsReportFrom').value)byId('qsReportFrom').value=localDate();if(byId('qsReportTo')&&!byId('qsReportTo').value)byId('qsReportTo').value=localDate(7);
}
function qualityStatusText(x){return ({open:'ждёт решения',waiting_rework:'ждёт доработки',passed:'годно',quarantined:'карантин',rework:'доработка',written_off:'списано',cancelled:'отменено',reworked_passed:'годно после доработки'})[x]||x||'';}
function renderQualitySupply(){
  const q=qualitySupplyData(),qc=q.quality||{},rp=q.replenishment||{},mt=q.maintenance||{};
  if(byId('qsQualityOpen'))byId('qsQualityOpen').textContent=String(qc.counts?.open||0);if(byId('qsQuarantine'))byId('qsQuarantine').textContent=String(qc.counts?.quarantine||0);if(byId('qsReplenish'))byId('qsReplenish').textContent=String(rp.counts?.suggested||0);if(byId('qsMaintenanceOverdue'))byId('qsMaintenanceOverdue').textContent=String(mt.counts?.overdue||0);
  const ins=byId('qsInspectionList');if(ins){ins.innerHTML='';const list=qc.inspections||[];ins.classList.toggle('empty',!list.length);if(!list.length)ins.textContent='Проверок пока нет';list.forEach(x=>{const row=document.createElement('div');row.className=`manager-row ${['quarantined','rework','written_off'].includes(x.status)?'danger-row':''}`;let actions='';if(x.can_decide&&['open','quarantined','rework'].includes(x.status)){actions+=`<button data-quality-action="${x.id}:pass">Годно</button><button data-quality-action="${x.id}:quarantine">Карантин</button><button data-quality-action="${x.id}:rework">Доработка</button><button class="danger" data-quality-action="${x.id}:write_off">Списать</button>`;}row.innerHTML=`<div><b>№${x.id} · ${escapeHtml(x.entity_name)} · ${escapeHtml(qualityStatusText(x.status))}</b><span>${escapeHtml(x.department_name||'')} · проверено ${escapeHtml(fmt(x.checked_quantity))} · несоответствие ${escapeHtml(fmt(x.defect_quantity))} ${escapeHtml(x.unit||'шт')}${x.lot_code?` · партия ${escapeHtml(x.lot_code)}`:''}${x.task_id?` · задание №${x.task_id}`:''}</span>${x.note?`<small>${escapeHtml(x.note)}</small>`:''}</div><div class="mini-actions">${actions}</div>`;ins.appendChild(row);});}
  const sug=byId('qsReplenishmentSuggestions');if(sug){sug.innerHTML='';const list=(rp.suggestions||[]).filter(x=>Number(x.recommended_quantity||0)>0||['warning','critical','emergency'].includes(x.severity));sug.classList.toggle('empty',!list.length);if(!list.length)sug.textContent='Рекомендаций нет';list.forEach(x=>{const row=document.createElement('div');row.className=`manager-row ${['critical','emergency'].includes(x.severity)?'danger-row':''}`;row.innerHTML=`<div><b>${escapeHtml(x.entity_name)} · ${escapeHtml(x.severity)}</b><span>${escapeHtml(x.area_name||'все площадки')} · запас ${x.reserve_shifts==null?'—':escapeHtml(fmt(x.reserve_shifts))} смен · доступно ${escapeHtml(fmt(x.available_quantity))} · рекомендуем ${escapeHtml(fmt(x.recommended_quantity))} ${escapeHtml(x.unit||'')}</span></div><div class="mini-actions">${Number(x.recommended_quantity||0)>0?`<button data-create-replenishment="${x.rule_id}">Создать заявку</button>`:''}</div>`;sug.appendChild(row);});}
  const req=byId('qsReplenishmentRequests');if(req){req.innerHTML='';const list=rp.requests||[];req.classList.toggle('empty',!list.length);if(!list.length)req.textContent='Заявок нет';list.forEach(x=>{const row=document.createElement('div');row.className='manager-row';let a='';if(x.can_manage&&x.status==='requested')a+=`<button data-replenishment-action="${x.id}:approve">Подтвердить</button>`;if(x.can_manage&&['requested','approved'].includes(x.status))a+=`<button data-replenishment-action="${x.id}:order">Заказано</button>`;if(x.can_manage&&['approved','ordered','partial'].includes(x.status))a+=`<button data-replenishment-action="${x.id}:receive">Получено</button>`;if(x.can_manage&&['requested','approved'].includes(x.status))a+=`<button class="danger" data-replenishment-action="${x.id}:reject">Отклонить</button>`;row.innerHTML=`<div><b>№${x.id} · ${escapeHtml(x.entity_name)} · ${escapeHtml(x.status)}</b><span>${escapeHtml(fmt(x.requested_quantity))} ${escapeHtml(x.unit||'')} · ${escapeHtml(x.area_name||'все площадки')}${x.needed_at?` · нужно ${escapeHtml(String(x.needed_at).slice(0,10))}`:''}</span></div><div class="mini-actions">${a}</div>`;req.appendChild(row);});}
  const ml=byId('qsMaintenanceList');if(ml){ml.innerHTML='';const list=mt.work_orders||[];ml.classList.toggle('empty',!list.length);if(!list.length)ml.textContent='Заданий ТО нет';list.forEach(x=>{const overdue=['planned','in_progress'].includes(x.status)&&new Date(String(x.due_at).replace(' ','T'))<new Date();const checks=(x.checks||[]).map(c=>`<label class="check-line"><input type="checkbox" data-maint-check="${x.id}:${c.id}" ${c.is_checked?'checked':''} ${!x.can_manage?'disabled':''}/> ${c.is_required?'* ':''}${escapeHtml(c.label)}</label>`).join('');const parts=(x.parts||[]).map(p=>`<small>${escapeHtml(p.entity_name)}: план ${escapeHtml(fmt(p.planned_quantity))}, факт ${escapeHtml(fmt(p.actual_quantity))} ${escapeHtml(p.unit||'')}</small>`).join('');let a='';if(x.can_manage&&x.status==='planned')a+=`<button data-maint-action="${x.id}:start">Начать</button>`;if(x.can_manage&&['planned','in_progress'].includes(x.status))a+=`<button data-maint-action="${x.id}:complete">Завершить</button>`;row.className=`manager-row ${overdue?'danger-row':''}`;row.innerHTML=`<div><b>ТО №${x.id} · ${escapeHtml(x.equipment_name)} · ${escapeHtml(x.status)}</b><span>срок ${escapeHtml(String(x.due_at||'').slice(0,16))}</span>${checks}${parts}</div><div class="mini-actions">${a}</div>`;ml.appendChild(row);});}
  renderQualitySupplyForms();
}
