async function qualitySupplyPost(url,body,ok){try{const r=await apiFetch(url,{method:'POST',headers,body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:(d.detail?.message||'Действие не выполнено.'));await refreshQualitySupply();showNotice(d.message||ok);}catch(e){showNotice(e.message||'Действие не выполнено.',true);}}
async function createQualityInspection(){const entityId=Number(val('qsInspectionEntity')||0);if(!entityId){showNotice('Выберите позицию.',true);return;}const ent=allVisibleEntities().find(x=>Number(x.id)===entityId);await qualitySupplyPost('/api/quality/inspections',{chat_id:Number(chatId),user_id:Number(userId),inspection_type:val('qsInspectionType')||'output',department_id:val('qsInspectionDepartment')?Number(val('qsInspectionDepartment')):null,entity_id:entityId,lot_id:val('qsInspectionLot')?Number(val('qsInspectionLot')):null,task_id:val('qsInspectionTask')?Number(val('qsInspectionTask')):null,equipment_id:val('qsInspectionEquipment')?Number(val('qsInspectionEquipment')):null,area_id:val('qsInspectionArea')?Number(val('qsInspectionArea')):null,checked_quantity:Number(String(val('qsChecked')||0).replace(',','.')),defect_quantity:Number(String(val('qsDefect')||0).replace(',','.')),unit:ent?.unit||'шт',note:val('qsInspectionNote')},'Контроль сохранён.');}
async function saveQualityRule(){const entityId=Number(val('qsRuleEntity')||0);if(!entityId){showNotice('Выберите позицию.',true);return;}await qualitySupplyPost('/api/quality/rules',{chat_id:Number(chatId),user_id:Number(userId),department_id:val('qsRuleDepartment')?Number(val('qsRuleDepartment')):null,entity_id:entityId,operation_type:'production',inspection_type:val('qsRuleType')||'output',sample_quantity:Number(String(val('qsRuleSample')||0).replace(',','.')),max_defect_percent:Number(String(val('qsRuleDefectPercent')||0).replace(',','.')),require_before_task_complete:byId('qsRuleRequired').checked,auto_quarantine_on_fail:byId('qsRuleQuarantine').checked,create_rework_task:byId('qsRuleRework').checked,rework_department_id:val('qsRuleReworkDepartment')?Number(val('qsRuleReworkDepartment')):null},'Правило сохранено.');}
async function qualityDecision(id,action){let reason='';if(action!=='pass'){reason=prompt('Причина решения:')||'';if(!reason)return;}await qualitySupplyPost('/api/quality/inspections/action',{chat_id:Number(chatId),user_id:Number(userId),inspection_id:Number(id),decision:action,reason},'Решение сохранено.');}
async function saveReplenishmentSetting(){const eid=Number(val('qsReplenishmentEntity')||0);if(!eid){showNotice('Выберите позицию.',true);return;}await qualitySupplyPost('/api/replenishment/settings',{chat_id:Number(chatId),user_id:Number(userId),entity_id:eid,area_id:val('qsReplenishmentArea')?Number(val('qsReplenishmentArea')):null,lead_time_days:Number(String(val('qsLeadDays')||0).replace(',','.')),target_cover_shifts:Number(String(val('qsCoverShifts')||10).replace(',','.')),minimum_order_quantity:Number(String(val('qsMinOrder')||0).replace(',','.')),pack_quantity:Number(String(val('qsPackQty')||0).replace(',','.')),preferred_supplier:val('qsSupplier')},'Настройка сохранена.');}
async function createRecommendedReplenishment(ruleId){const x=(qualitySupplyData().replenishment?.suggestions||[]).find(v=>Number(v.rule_id)===Number(ruleId));if(!x)return;await qualitySupplyPost('/api/replenishment/requests',{chat_id:Number(chatId),user_id:Number(userId),entity_id:Number(x.entity_id),area_id:x.area_id?Number(x.area_id):null,requested_quantity:Number(x.recommended_quantity||0),unit:x.unit||'шт',source:'forecast',source_rule_id:Number(x.rule_id),recommended_quantity:Number(x.recommended_quantity||0),lead_time_days:Number(x.lead_time_days||0),needed_at:x.needed_at||null,reason:x.reason||'Прогноз дефицита'},'Заявка создана.');}
async function replenishmentAction(id,action){let reason='';if(['reject','cancel'].includes(action)){reason=prompt('Причина:')||'';if(!reason)return;}await qualitySupplyPost('/api/replenishment/requests/action',{chat_id:Number(chatId),user_id:Number(userId),request_id:Number(id),action,reason},'Заявка обновлена.');}
async function saveMaintenancePlan(){const eid=Number(val('qsMaintenanceEquipment')||0);if(!eid){showNotice('Выберите оборудование.',true);return;}const checklist=String(val('qsMaintenanceChecklist')||'').split(/\n+/).map((x,i)=>{const t=x.trim();return t?{label:t.replace(/^\?\s*/,''),is_required:!/^\?/.test(t)}:null;}).filter(Boolean);const spare_parts=[];const pe=Number(val('qsMaintenancePartEntity')||0),pq=Number(String(val('qsMaintenancePartQty')||0).replace(',','.'));if(pe&&pq>0){const ent=allVisibleEntities().find(x=>Number(x.id)===pe);spare_parts.push({entity_id:pe,planned_quantity:pq,area_id:val('qsMaintenancePartArea')?Number(val('qsMaintenancePartArea')):null,unit:ent?.unit||'шт'});}await qualitySupplyPost('/api/maintenance/plans',{chat_id:Number(chatId),user_id:Number(userId),equipment_id:eid,responsible_user_id:val('qsMaintenanceResponsible')?Number(val('qsMaintenanceResponsible')):null,interval_days:Number(val('qsMaintenanceInterval')||0),warning_before_days:Number(val('qsMaintenanceWarning')||3),next_due_at:val('qsMaintenanceDue')||null,checklist,note:val('qsMaintenanceNote'),spare_parts},'План ТО сохранён.');}
async function maintenanceAction(id,action){let result='';if(action==='complete'){result=prompt('Результат обслуживания:')||'';if(!result)return;}await qualitySupplyPost('/api/maintenance/work/action',{chat_id:Number(chatId),user_id:Number(userId),work_order_id:Number(id),action,result},'ТО обновлено.');}
async function maintenanceCheck(workId,checkId,checked){await qualitySupplyPost('/api/maintenance/work/check',{chat_id:Number(chatId),user_id:Number(userId),work_order_id:Number(workId),check_id:Number(checkId),checked},'Чек-лист обновлён.');}
async function downloadNeedsReport(format){try{const q=new URLSearchParams({chat_id:chatId,user_id:userId,format,start_date:val('qsReportFrom'),end_date:val('qsReportTo')});const r=await apiFetch('/api/production-needs-report?'+q.toString(),{headers},60000);if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.detail||'Отчёт не собран.');}await downloadBlob(r,format==='pdf'?'plan_need_stock.pdf':'plan_need_stock.xlsx');}catch(e){showNotice(e.message||'Отчёт не собран.',true);}}

