function bytesText(n){const v=Number(n||0);if(v<1024)return `${v} Б`;if(v<1024**2)return `${(v/1024).toFixed(1)} КБ`;if(v<1024**3)return `${(v/1024**2).toFixed(1)} МБ`;return `${(v/1024**3).toFixed(1)} ГБ`;}
function renderDiagnostics(){const d=state.diagnostics,box=byId('diagnosticsStatus'),errors=byId('diagnosticsErrors');if(!box||!d)return;box.innerHTML='';const rows=[['База данных',`${d.database?.status==='ok'?'OK':'ОШИБКА'} · ${d.database?.message||''} · ${bytesText(d.database?.size_bytes)}`,d.database?.status==='ok'],['Бот',`${d.services?.bot?.stale?'нет свежего сигнала':'работает'} · ${d.services?.bot?.last_seen_at||'нет данных'}`,!d.services?.bot?.stale],['Mini App',`${d.services?.miniapp?.stale?'нет свежего сигнала':'работает'} · ${d.services?.miniapp?.last_seen_at||'нет данных'}`,!d.services?.miniapp?.stale],['Планировщик',`${d.services?.scheduler?.stale?'нет свежего сигнала':'работает'} · ${d.services?.scheduler?.last_seen_at||'нет данных'}`,!d.services?.scheduler?.stale],['Диск',`свободно ${bytesText(d.disk?.free_bytes)} (${d.disk?.free_percent||0}%)`,Number(d.disk?.free_percent||0)>10],['Очереди',`Telegram ${d.queues?.telegram_pending||0} · отчёты ${d.queues?.report_queued||0} · ошибки отчётов ${d.queues?.report_errors||0} · пакеты ${d.queues?.shift_packages_unresolved||0}`,Number(d.queues?.report_errors||0)===0],['Производственный контур',`задания ${d.workflow?.active_tasks||0} · заявки ${d.workflow?.open_requests||0} · качество ${d.workflow?.quality_open||0} · карантин ${d.workflow?.quarantine_lots||0} · пополнение ${d.workflow?.replenishment_open||0} · ТО просрочено ${d.workflow?.maintenance_work_overdue||0} · восстановление ${d.workflow?.reliability_pending||0}`,Number(d.workflow?.open_downtimes||0)===0],['Резервные копии',d.backup?.latest?`${d.backup.count} · последняя ${d.backup.latest.modified_at}`:'копий нет',!!d.backup?.latest]];rows.forEach(([name,value,ok])=>{const row=document.createElement('div');row.className=`manager-row ${ok?'system-ok':'system-bad'}`;row.innerHTML=`<div><b>${escapeHtml(name)}</b><span>${escapeHtml(value)}</span></div>`;box.appendChild(row);});box.classList.remove('empty');if(errors){errors.innerHTML='';const list=d.recent_errors||[];errors.classList.toggle('empty',!list.length);if(!list.length)errors.textContent='Последних ошибок нет';list.forEach(x=>{const row=document.createElement('div');row.className='manager-row system-bad';row.innerHTML=`<div><b>${escapeHtml(x.source)} · №${escapeHtml(x.ref_id)}</b><span>${escapeHtml(x.message)} · ${escapeHtml(String(x.created_at||'').slice(0,16))}</span></div>`;errors.appendChild(row);});}}
