async function queuePresetBatch(presetId){const raw=prompt('Множители базового количества через запятую. Например: 1, 1, 2 или 1, 5, 10','1,1,1');if(!raw)return;const multipliers=raw.split(/[;,\s]+/).map(x=>Number(String(x).replace(',','.'))).filter(x=>x>0).slice(0,50);if(!multipliers.length){showNotice('Не указаны количества.',true);return;}try{const res=await apiFetch('/api/operation-presets/batch',{method:'POST',headers,body:JSON.stringify({chat_id:Number(chatId),user_id:Number(userId),preset_id:Number(presetId),multipliers})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||'Пакет не создан.');let added=0;(data.items||[]).forEach(item=>{const body={chat_id:Number(chatId),user_id:Number(userId),...item,client_request_id:newRequestId()};if(enqueueOperation(body,'',false))added+=1;});showNotice(`В список смены добавлено: ${added}.`);}catch(e){showNotice(e.message||'Пакет не создан.',true);}}

async function load(){
  if(!userId || !initData){ renderRows(byId('alerts'), [{name:'Доступ закрыт', value:'откройте Mini App кнопкой внутри Telegram-бота'}]); return; }
  if(!chatId){ await loadAccounts(); if(!state.accounts.length) renderRows(byId('alerts'), [{name:'Учёт не выбран', value:'откройте группу в боте'}]); return; }
  const res = await fetch(`/api/bootstrap?chat_id=${encodeURIComponent(chatId)}&user_id=${encodeURIComponent(userId)}`, {headers});
  if(!res.ok){ renderRows(byId('alerts'), [{name:'Нет доступа', value:'проверьте выбранный учёт'}]); return; }
  const data = await res.json(); state = {...state, ...data}; byId('accountName').textContent = data.account?.name || 'Учёт'; fillForms(); renderDashboard(data.dashboard||{}); renderOperationShortcuts(); renderSetupHealth(); renderControlSummary(); renderWorkflow(); renderQualitySupply(); applyAccess(); await loadAudit(); renderAccounts();
  loadOperationQueue();if(!byId('workOperation')?.dataset.draftRestored){restoreWorkDraft();byId('workOperation').dataset.draftRestored='1';}
  const savedTab = localStorage.getItem('prodMiniTab'); const savedPage=savedTab?byId(`page-${savedTab}`):null; if(savedTab&&savedPage&&!savedPage.classList.contains('hidden-by-access')&&!document.querySelector(`[data-tab="${savedTab}"]`)?.classList.contains('hidden')) showTab(savedTab); else if(state.workspace?.home_tab)showTab(state.workspace.home_tab); else if((state.work_access||[]).length)showTab('work');
}
function val(id){return byId(id)?.value || '';}
function qty(id){return Number(String(val(id)).replace(',','.').replace(/\s+/g,''));}
async function postOperation(kind, etype, eid, amount, areaId, extra={}){
  if(!eid || !amount || amount<=0){showNotice('Укажите позицию и количество.', true); return;}
  const item=(state.entities?.[etype]||[]).find(x=>String(x.id)===String(eid));
  const body={chat_id:Number(chatId),user_id:Number(userId),operation_type:kind,entity_type:etype,entity_id:Number(eid),quantity:amount,unit:item?.unit||'шт',area_id:areaId?Number(areaId):null,...extra};
  await startOperationFlow(body);
}
function parseTargets(){return String(val('planTargets')).split(/[;,\s]+/).map(x=>Number(x.replace(',','.'))).filter(x=>x>0);}
