  const replAct=e.target.closest('[data-replenishment-action]')?.dataset.replenishmentAction;if(replAct){const [id,a]=replAct.split(':');replenishmentAction(id,a);return;}
  const maintAct=e.target.closest('[data-maint-action]')?.dataset.maintAction;if(maintAct){const [id,a]=maintAct.split(':');maintenanceAction(id,a);return;}
  const tab=e.target.closest('[data-tab]')?.dataset.tab; if(tab){showTab(tab);return;}
  const action=e.target.closest('[data-action]')?.dataset.action; if(!action)return;
  if(action==='save-work-entry') { saveWorkEntry(); return; }
  if(action==='queue-work-entry') { queueCurrentOperation(); return; }
  if(action==='sync-operation-queue') { syncOperationQueue(false); return; }
