  if(action==='download-needs-xlsx') { downloadNeedsReport('xlsx'); return; }
  if(action==='download-needs-pdf') { downloadNeedsReport('pdf'); return; }
  if(action==='create-production-task') { createProductionTask(); return; }
  if(action==='create-department-request') { createDepartmentRequest(); return; }
  if(action==='create-production-lot') { createProductionLot(); return; }
  if(action==='save-equipment') { saveWorkflowEquipment(); return; }
  if(action==='load-plan-fact') { loadWorkflowPlanFact(); return; }
