  if(action==='load-diagnostics') { loadDiagnostics(); return; }
  if(action==='clear-package-filters') { clearPackageFilters(); return; }
  if(action==='bulk-approve-packages') { bulkReviewShiftPackages('approve'); return; }
  if(action==='bulk-reject-packages') { bulkReviewShiftPackages('reject'); return; }
  if(action==='create-shift-handover') { createShiftHandover(); return; }
  if(action==='print-selected-labels') { printEntityLabels(false); return; }
  if(action==='print-all-labels') { printEntityLabels(true); return; }
  if(action==='save-label-template') { saveLabelTemplate(); return; }
  if(action==='save-continuity-settings') { saveContinuitySettings(); return; }
  if(action==='save-handover-checklist') { saveHandoverChecklist(); return; }
  if(action==='download-continuity-audit') { downloadContinuityAudit(); return; }
